mapper.update:
UPDATE workspaces
SET name = #{params.Name},
    data_residency = CAST(#{params.DataResidency} AS jsonb),
    external_key_id = #{params.ExternalKeyID},
    tags = CAST(#{params.Tags} AS jsonb),
    updated_at = #{params.UpdatedAt}
WHERE organization_uuid = #{params.OrganizationUUID}
AND external_id = #{params.ExternalID}
RETURNING

UPDATE workspaces
SET archived_at = COALESCE(archived_at, NOW()),
    updated_at = NOW()
WHERE organization_uuid = #{organizationUUID}
AND external_id = #{externalID}
RETURNING

